mixed-shared-group-key-filter.specification:
yamaa: "1.0"
type: spec
domain: TEST
keys: [ID, SECTION, SEQ]
input: {SRC: {path: input.csv, types: {SEQ: int}}}
output: {path: result.csv, columns: [ID, SECTION, SEQ, VALUE]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - {name: SECTION, type: str}
  - {name: SEQ, type: int}
  - {name: VALUE, type: str, derivation: {case: [{when: 'TRUE', then: {source: {variable: SRC.ID, filter: 'SRC.SEQ > 0'}}}, {otherwise: "'unused'"}]}}
rows:
  - {id: grouped, dataset: SRC, group_by: [SRC.ID], derivations: {SECTION: "'grouped'", SEQ: 0}}
  - {id: records, dataset: SRC, derivations: {SECTION: "'record'", SEQ: SRC.SEQ}}

